# Kurs Motorsteuergerät · Modul 5–8
from common import *

M5 = {"id": "ecu.m5", "level": 2, "title": "Bussysteme und Vernetzung", "desc": "CAN, CAN FD, FlexRay, LIN, Automotive Ethernet, Sub-Busse und Netzwerkmanagement.", "lessons": [
 L("ecu.m5.l1", "CAN und CAN FD", 7, [
  "Das Controller Area Network (CAN) ist seit Jahrzehnten das Rückgrat der Fahrzeugkommunikation. Alle Teilnehmer hängen an zwei verdrillten Leitungen (CAN-High und CAN-Low) und senden Nachrichten mit einer Kennung (ID), nicht an eine Adresse.",
  "## Arbitrierung",
  "Wollen zwei Steuergeräte gleichzeitig senden, gewinnt die Nachricht mit der kleineren ID, ohne dass Daten verloren gehen: Ein dominantes Bit (0) überschreibt ein rezessives (1). Wer ein rezessives Bit sendet und ein dominantes liest, hört auf. Kleine IDs haben deshalb hohe Priorität.",
  "## Klassisches CAN",
  "Ein klassischer CAN-Frame trägt höchstens 8 Byte Nutzdaten, bei typischen 500 kbit/s im Antriebsbereich. Eine Prüfsumme (CRC) und Bestätigung (ACK) sichern die Übertragung; Steuergeräte mit vielen Fehlern schalten sich selbst vom Bus ab (Bus-Off).",
  "## CAN FD",
  "CAN FD (Flexible Data-Rate) erlaubt bis zu 64 Byte pro Frame und schaltet in der Datenphase auf eine höhere Bitrate um, oft 2 bis 5 Mbit/s. Die Arbitrierung läuft weiter langsam, damit sie bei der Leitungslänge funktioniert. So passt deutlich mehr Information durch denselben Bus, etwa für Flashen oder gesicherte Botschaften mit Signatur.",
  "## Absicherung der Inhalte",
  "Für sicherheitsrelevante Signale werden Zähler und Prüfsummen in die Nutzdaten gepackt (in AUTOSAR: End-to-End-Protection), damit der Empfänger veraltete oder verfälschte Werte erkennt."],
  ["CAN: Nachrichten mit ID, kleinere ID gewinnt die Arbitrierung.", "Klassisch bis 8 Byte; CAN FD bis 64 Byte mit schnellerer Datenphase.", "E2E-Schutz: Zähler und CRC im Inhalt sicherheitsrelevanter Signale."],
  [S_CIA, S_BUS, S_AUTOSAR],
  [card("CAN-Arbitrierung", "Bitweiser Wettstreit beim gleichzeitigen Senden: Dominante 0 gewinnt, die kleinere ID setzt sich verlustfrei durch."),
   card("CAN FD", "Weiterentwicklung von CAN mit bis zu 64 Byte Nutzdaten und höherer Bitrate in der Datenphase."),
   card("Bus-Off", "Zustand, in dem ein Steuergerät mit zu vielen Fehlern nicht mehr am Bus sendet."),
   card("E2E-Protection", "Schutz von Signalinhalten durch Zähler und Prüfsumme, um Verlust, Wiederholung oder Verfälschung zu erkennen.")],
  [mc("Zwei Steuergeräte senden gleichzeitig: ID 0x120 und ID 0x0F0. Wer gewinnt?", ["0x0F0", "0x120", "Beide kollidieren und senden neu", "Das zuerst eingeschaltete"], 0, "Die kleinere ID hat mehr führende dominante Bits."),
   num("Wie viele Byte Nutzdaten passen höchstens in einen CAN-FD-Frame?", 64, "Byte", 0, "Klassisches CAN: 8 Byte, CAN FD: bis 64 Byte."),
   mc("Warum bleibt die Arbitrierungsphase bei CAN FD langsam?", ["Alle Teilnehmer müssen das Bit gleichzeitig sehen", "Um Strom zu sparen", "Weil die ID verschlüsselt ist", "Weil die Norm es aus Kostengründen verlangt"], 0, "Bei der Arbitrierung müssen sich die Signale über die ganze Leitung ausbreiten."),
   mc("Wozu dient ein Botschaftszähler im Nutzinhalt?", ["Veraltete oder wiederholte Nachrichten erkennen", "Die Bitrate erhöhen", "Die ID verkürzen", "Den Bus wecken"], 0, "Bleibt der Zähler stehen, ist der Sender ausgefallen oder die Nachricht alt.")]),
 L("ecu.m5.l2", "FlexRay, LIN und Ethernet", 7, [
  "Nicht jede Aufgabe passt zu CAN. Im Fahrzeug arbeiten deshalb mehrere Bussysteme nebeneinander.",
  "## FlexRay",
  "FlexRay arbeitet mit bis zu 10 Mbit/s pro Kanal und hat einen festen Zeitplan: Jeder Teilnehmer bekommt im statischen Segment eines Zyklus seine Zeitschlitze (TDMA). Dadurch ist genau vorhersagbar, wann eine Nachricht ankommt (deterministisch). Zwei Kanäle können redundant genutzt werden. Ein dynamisches Segment bietet zusätzlich Platz für ereignisgesteuerte Nachrichten. FlexRay wurde vor allem für Fahrwerk, Antrieb und sicherheitsrelevante Verbünde eingesetzt; in neuen Architekturen wird es oft durch CAN FD und Ethernet ersetzt.",
  "## LIN",
  "Das Local Interconnect Network ist ein einfacher, günstiger Eindrahtbus mit bis zu etwa 20 kbit/s. Ein Master fragt Slaves zyklisch ab (Master-Slave). Typische Teilnehmer sind intelligente Sensoren und Aktoren, zum Beispiel Generator- oder Batteriesensoren, Klappen oder Lüfter.",
  "## Automotive Ethernet",
  "Für hohe Datenmengen (Kameras, Zentralrechner, Backbone) wird Ethernet über ein einzelnes verdrilltes Adernpaar genutzt, etwa 100BASE-T1 oder 1000BASE-T1. Darauf laufen Protokolle wie SOME/IP für Dienste und DoIP für Diagnose und Flashen.",
  "## Sub-Busse",
  "Häufig bildet ein Steuergerät mit seinen direkten Partnern einen eigenen, abgeschotteten Bus, oft Sub-CAN oder privater CAN genannt. Beispiele sind Verbindungen zu einem Getriebesteuergerät oder intelligenten Aktoren. Das entlastet die Hauptbusse und trennt sicherheitskritische Kommunikation. Wie solche Busse heißen und aufgebaut sind, ist herstellerspezifisch."],
  ["FlexRay: festes Zeitraster, deterministisch, bis 10 Mbit/s, zwei Kanäle.", "LIN: einfacher Master-Slave-Eindrahtbus bis ca. 20 kbit/s.", "Ethernet (T1) für hohe Datenraten; Sub-Busse trennen lokale Verbünde ab."],
  [S_BUS, S_AUTOSAR],
  [card("FlexRay", "Deterministischer Bus mit festem Zeitplan (TDMA), bis 10 Mbit/s je Kanal, zwei Kanäle möglich."),
   card("TDMA", "Zeitmultiplex: Jeder Teilnehmer sendet nur in fest zugeteilten Zeitschlitzen."),
   card("LIN", "Einfacher Eindrahtbus für Sensoren und Aktoren; ein Master steuert alle Übertragungen."),
   card("100BASE-T1", "Automotive Ethernet mit 100 Mbit/s über ein einzelnes verdrilltes Adernpaar."),
   card("Sub-CAN / privater CAN", "Lokaler CAN-Verbund eines Steuergeräts mit direkten Partnern, getrennt vom Hauptnetz (herstellerspezifisch)."),
   card("DoIP", "Diagnose über IP (ISO 13400): UDS-Kommunikation über Ethernet.")],
  [mc("Was ist die besondere Stärke von FlexRay?", ["Deterministisches Zeitverhalten", "Sehr niedrige Kosten", "Nur ein Draht", "Kabellose Übertragung"], 0, "Das feste Zeitraster garantiert, wann jede Nachricht kommt."),
   mc("Wie wird beim LIN-Bus gesendet?", ["Der Master fragt die Slaves ab", "Jeder sendet frei mit Arbitrierung", "Nach festen Zeitslots ohne Master", "Über Funk"], 0, "LIN arbeitet streng nach dem Master-Slave-Prinzip."),
   mc("Welcher Bus passt am besten für eine Frontkamera mit hoher Datenrate?", ["Automotive Ethernet", "LIN", "Klassisches CAN", "Klemme 15"], 0, "Videodaten brauchen Bandbreiten im Bereich von 100 Mbit/s und mehr."),
   mc("Wozu dient ein Sub-CAN?", ["Lokale Kommunikation vom Hauptnetz trennen", "Die Batterie zu laden", "Den LIN-Bus zu ersetzen", "Fehlerspeicher zu löschen"], 0, "Er entlastet die Hauptbusse und schottet lokale Verbünde ab."),
   order("Ordne nach typischer maximaler Datenrate, von niedrig nach hoch.", ["LIN", "Klassisches CAN", "FlexRay", "1000BASE-T1"], "Etwa 20 kbit/s, 1 Mbit/s, 10 Mbit/s, 1 Gbit/s.")]),
 L("ecu.m5.l3", "Netzwerkmanagement und Gateway", 5, [
  "Damit die Batterie nicht leer wird, müssen alle Steuergeräte eines Busses gemeinsam einschlafen und aufwachen. Das regelt das Netzwerkmanagement.",
  "## So funktioniert es",
  "Jedes Steuergerät, das den Bus noch braucht, sendet regelmäßig eine Netzwerkmanagement-Botschaft. Hört ein Steuergerät eine Weile keine solche Botschaft mehr und braucht selbst nichts, bereitet es den Schlaf vor. Schweigen alle, schläft der ganze Bus ein. Eine neue Botschaft weckt ihn wieder. In AUTOSAR heißt das Modul CanNm (bzw. FrNm für FlexRay).",
  "## Teilnetzbetrieb",
  "Beim Partial Networking schlafen nur die Steuergeräte, die gerade nicht gebraucht werden, während andere auf demselben Bus weiterarbeiten. Spezielle Transceiver wachen nur bei bestimmten Botschaften auf. Das spart Energie, gerade wenn im Stand Funktionen wie Klimatisierung oder Laden laufen.",
  "## Gateway",
  "Ein Gateway-Steuergerät verbindet die verschiedenen Busse, leitet Signale weiter, übersetzt zwischen Protokollen und schützt als Firewall die inneren Netze. Diagnosezugriffe von außen gehen meist zuerst durch das Gateway."],
  ["Netzwerkmanagement: Alle schlafen gemeinsam, eine Botschaft weckt alle.", "Partial Networking: Nur benötigte Steuergeräte bleiben wach.", "Gateway verbindet Busse und wirkt als Firewall."],
  [S_AUTOSAR],
  [card("Netzwerkmanagement (NM)", "Koordiniert gemeinsames Einschlafen und Aufwachen der Steuergeräte eines Busses."),
   card("Partial Networking", "Teilnetzbetrieb: Ein Teil der Steuergeräte schläft, während andere auf demselben Bus weiterkommunizieren."),
   card("Gateway", "Steuergerät, das Busse verbindet, Botschaften weiterleitet und Zugriffe filtert.")],
  [mc("Ein Steuergerät hört keine NM-Botschaften mehr und braucht den Bus nicht. Was tut es?", ["Es bereitet den Schlaf vor", "Es sendet Fehlercodes", "Es erhöht die Bitrate", "Es startet neu"], 0, "Das ist das Grundprinzip des koordinierten Einschlafens."),
   mc("Was spart Partial Networking?", ["Energie, weil nicht alle Steuergeräte wach sind", "Kabel, weil weniger Busse nötig sind", "Rechenzeit im Motorsteuergerät", "Speicher im Flash"], 0, "Nur benötigte Teilnehmer bleiben aktiv."),
   mc("Welche Aufgabe hat ein zentrales Gateway nicht?", ["Einspritzventile ansteuern", "Botschaften zwischen Bussen weiterleiten", "Zugriffe von außen filtern", "Zwischen Protokollen übersetzen"], 0, "Die Einspritzung steuert das Motorsteuergerät selbst."),
   mc("Wie heißt das AUTOSAR-Modul für das Netzwerkmanagement auf CAN?", ["CanNm", "EcuM", "Dem", "Xcp"], 0, "EcuM steuert Steuergerätezustände, Dem den Fehlerspeicher.")])
]}

M6 = {"id": "ecu.m6", "level": 2, "title": "Software und Konfiguration", "desc": "AUTOSAR-Schichten, Datenstand, Kalibrierung über A2L und XCP, Codierung und Flashen.", "lessons": [
 L("ecu.m6.l1", "Die Software-Architektur", 7, [
  "Die Software eines modernen Steuergeräts ist in Schichten aufgebaut, verbreitet nach dem Standard AUTOSAR Classic Platform.",
  "## Die Schichten",
  "Ganz unten abstrahiert der Microcontroller Abstraction Layer die Hardware (Treiber für ADC, Timer, CAN). Darüber liegen die Basissoftware-Dienste: Kommunikation, Speicherverwaltung, Diagnose (Fehlerspeicher Dem, Diagnosekommunikation Dcm), Zustandsverwaltung und das Betriebssystem. Die Runtime Environment (RTE) verbindet die Basissoftware mit den Anwendungskomponenten (Software Components), in denen die eigentlichen Motorfunktionen stecken.",
  "## Betriebssystem und Tasks",
  "Ein Echtzeitbetriebssystem (AUTOSAR OS, aus OSEK hervorgegangen) startet Tasks in festen Zeitrastern, etwa alle 1, 10 oder 100 ms, und winkelsynchron zur Kurbelwelle. Prioritäten sorgen dafür, dass zeitkritische Aufgaben zuerst dran sind.",
  "## Warum Schichten?",
  "Funktionen können wiederverwendet und auf andere Hardware portiert werden, Zulieferer und Hersteller können getrennt entwickeln. Ein Teil der Software, besonders bei Motorsteuerungen, ist allerdings nicht nach AUTOSAR strukturiert, sondern herstellerspezifisch."],
  ["AUTOSAR-Schichten: MCAL → Basissoftware → RTE → Anwendung.", "Echtzeit-OS startet Tasks zeit- und winkelsynchron.", "Schichten ermöglichen Wiederverwendung und getrennte Entwicklung."],
  [S_AUTOSAR],
  [card("MCAL", "Microcontroller Abstraction Layer: unterste AUTOSAR-Schicht mit Hardwaretreibern."),
   card("RTE", "Runtime Environment: verbindet Anwendungskomponenten mit der Basissoftware und untereinander."),
   card("Dem", "Diagnostic Event Manager: AUTOSAR-Modul für Fehlerspeicher und Fehlerstatus."),
   card("Dcm", "Diagnostic Communication Manager: AUTOSAR-Modul, das Diagnoseanfragen (z. B. UDS) beantwortet."),
   card("Task", "Programmteil, den das Betriebssystem zyklisch, ereignis- oder winkelgesteuert startet.")],
  [order("Ordne die AUTOSAR-Schichten von unten (Hardware) nach oben.", ["Mikrocontroller", "MCAL", "Basissoftware-Dienste", "RTE", "Anwendungskomponenten"], "Die RTE trennt Anwendung und Basissoftware."),
   mc("Welches AUTOSAR-Modul verwaltet den Fehlerspeicher?", ["Dem", "Dcm", "RTE", "MCAL"], 0, "Dcm beantwortet Diagnoseanfragen und holt die Daten beim Dem."),
   mc("Was verbindet Anwendungskomponenten mit der Basissoftware?", ["RTE", "Bootloader", "Watchdog", "Gateway"], 0, "Die Runtime Environment ist die Zwischenschicht."),
   mc("Warum laufen manche Tasks winkelsynchron statt zeitgesteuert?", ["Weil Zündung und Einspritzung am Kurbelwinkel hängen", "Weil sie weniger Speicher brauchen", "Weil das Betriebssystem keine Zeit kennt", "Weil sie nur im Leerlauf laufen"], 0, "Motorvorgänge richten sich nach dem Winkel, nicht nach der Uhr.")]),
 L("ecu.m6.l2", "Datenstand und Kalibrierung", 7, [
  "Dieselbe Software kann sehr verschiedene Motoren steuern. Den Unterschied machen die Kalibrierdaten (Datenstand, Applikationsdaten).",
  "## Programm und Daten",
  "Das Programm enthält die Algorithmen. Die Daten legen fest, wie sie sich verhalten: Kennwerte (einzelne Zahlen), Kennlinien (eine Eingangsgröße) und Kennfelder (zwei Eingangsgrößen, etwa Zündwinkel über Drehzahl und Last). Ein Motorsteuergerät hat davon oft zehntausende.",
  "## Applikation",
  "Applikationsingenieure stimmen diese Daten am Prüfstand und im Fahrzeug ab. Dafür verbindet sich ein Mess- und Kalibrierwerkzeug mit dem Steuergerät, typischerweise über das Protokoll XCP (über CAN, CAN FD, FlexRay oder Ethernet). Es kann Variablen in Echtzeit messen und Parameter im laufenden Betrieb verstellen.",
  "## Die A2L-Datei",
  "Damit das Werkzeug weiß, an welcher Speicheradresse welcher Wert liegt, in welcher Einheit und mit welcher Umrechnung, gibt es eine Beschreibungsdatei im ASAM-Format A2L. Sie passt immer genau zu einem Softwarestand.",
  "## Sicherheit",
  "Im Serienfahrzeug sind Kalibrierzugänge gesperrt oder abgesichert, damit niemand unbemerkt Abgas- oder Sicherheitsverhalten verändern kann."],
  ["Programm (Algorithmen) und Daten (Kennwerte, Kennlinien, Kennfelder) sind getrennt.", "XCP: Messen und Verstellen im laufenden Betrieb.", "A2L beschreibt Adressen, Einheiten und Umrechnungen für einen Softwarestand."],
  [S_XCP, S_A2L, S_REIF],
  [card("Kennfeld", "Tabelle mit zwei Eingangsgrößen, z. B. Zündwinkel über Drehzahl und Last; dazwischen wird interpoliert."),
   card("Kennlinie", "Tabelle mit einer Eingangsgröße."),
   card("XCP", "ASAM-Protokoll zum Messen und Kalibrieren von Steuergeräten im laufenden Betrieb."),
   card("A2L", "ASAM-Beschreibungsdatei mit Adressen, Datentypen und Umrechnungen der Mess- und Kalibriergrößen."),
   card("Applikation", "Abstimmung der Kalibrierdaten eines Steuergeräts auf Motor und Fahrzeug.")],
  [mc("Was ist ein Kennfeld?", ["Eine Tabelle mit zwei Eingangsgrößen", "Ein Fehlerspeichereintrag", "Ein Busprotokoll", "Ein Speicherbereich für Variablen"], 0, "Beispiel: Zündwinkel abhängig von Drehzahl und Last."),
   mc("Wozu dient die A2L-Datei?", ["Sie beschreibt, wo welche Größe im Speicher liegt", "Sie enthält den Programmcode", "Sie verschlüsselt den Bus", "Sie speichert Fehlercodes"], 0, "Ohne A2L wüsste das Werkzeug nicht, wie es Rohdaten deuten soll."),
   mc("Was kann man mit XCP tun?", ["Messen und Parameter im Betrieb verstellen", "Nur Fehler auslesen", "Nur Software flashen", "Das Fahrzeug orten"], 0, "XCP ist das Mess- und Kalibrierprotokoll."),
   mc("Warum muss die A2L genau zum Softwarestand passen?", ["Adressen ändern sich mit jeder Softwareversion", "Sonst ist die Datei zu groß", "Weil der Bus sonst langsamer wird", "Das ist nur eine Konvention"], 0, "Neue Software kann Größen an andere Adressen legen.")]),
 L("ecu.m6.l3", "Varianten und Codierung", 5, [
  "Ein Motorsteuergerät wird oft für viele Fahrzeugvarianten genutzt: andere Getriebe, Länder, Abgasnormen oder Ausstattungen. Statt für jede eine eigene Software zu bauen, nutzt man Varianten im Datenstand und Codierung.",
  "## Codierung",
  "Bei der Codierung schreibt ein Werkstatt- oder Bandtester Konfigurationswerte in das Steuergerät, meist per UDS-Dienst WriteDataByIdentifier (0x2E). Sie aktivieren oder deaktivieren Funktionen, zum Beispiel ob eine Anhängerkupplung verbaut ist.",
  "## Variantenauswahl",
  "Alternativ enthält der Datenstand mehrere Datensätze, und das Steuergerät wählt beim Start den passenden aus, etwa über eine Fahrzeugkennung vom Bus.",
  "## Lernwerte",
  "Davon zu unterscheiden sind Lernwerte, die das Steuergerät im Betrieb selbst ermittelt, etwa Adaptionen von Gemisch oder Drosselklappe. Sie werden im nichtflüchtigen Speicher abgelegt und nach Reparaturen gegebenenfalls zurückgesetzt."],
  ["Varianten über Codierung oder Datensatzauswahl statt eigener Software.", "Codierung meist per UDS 0x2E.", "Lernwerte ermittelt das Steuergerät im Betrieb selbst."],
  [S_UDS, S_REIF],
  [card("Codierung", "Schreiben von Konfigurationswerten, die Funktionen einer Variante aktivieren oder deaktivieren."),
   card("UDS 0x2E", "WriteDataByIdentifier: schreibt einen Datenwert unter einer Kennung (DID)."),
   card("Lernwert (Adaption)", "Vom Steuergerät im Betrieb ermittelter Korrekturwert, z. B. für das Gemisch.")],
  [mc("Mit welchem UDS-Dienst wird typischerweise codiert?", ["WriteDataByIdentifier (0x2E)", "ReadDTCInformation (0x19)", "TesterPresent (0x3E)", "ECUReset (0x11)"], 0, "0x2E schreibt Daten unter einer Kennung."),
   mc("Was unterscheidet Lernwerte von Codierwerten?", ["Lernwerte ermittelt das Steuergerät selbst", "Lernwerte schreibt die Werkstatt", "Lernwerte liegen im RAM und gehen verloren", "Es gibt keinen Unterschied"], 0, "Codierwerte kommen von außen, Lernwerte entstehen im Betrieb."),
   mc("Warum nutzt man Codierung statt einer eigenen Software je Variante?", ["Weniger Softwarestände, die gepflegt werden müssen", "Weil Codierung schneller rechnet", "Weil Software nicht kopierbar ist", "Weil die Norm es verlangt"], 0, "Jeder Softwarestand muss entwickelt, getestet und freigegeben werden."),
   mc("Wann ist ein Zurücksetzen von Lernwerten sinnvoll?", ["Nach dem Tausch eines betroffenen Bauteils", "Bei jedem Tankstopp", "Bei jedem Start", "Nie"], 0, "Die alten Adaptionen passen nicht mehr zum neuen Bauteil.")])
]}

M7 = {"id": "ecu.m7", "level": 3, "title": "Funktionale Sicherheit", "desc": "ISO 26262, ASIL, das E-Gas-Überwachungskonzept und der Umgang mit Fehlern.", "lessons": [
 L("ecu.m7.l1", "ISO 26262 und ASIL", 7, [
  "Fehlfunktionen elektronischer Systeme dürfen niemanden gefährden. Die Norm ISO 26262 beschreibt, wie man sicherheitsrelevante Fahrzeugelektronik entwickelt.",
  "## Gefährdungs- und Risikoanalyse",
  "Zuerst wird untersucht, welche Fehlfunktionen gefährlich sein können, etwa ungewolltes Beschleunigen. Jede Gefährdung wird nach drei Kriterien bewertet: Schwere (Severity), Häufigkeit der Fahrsituation (Exposure) und Beherrschbarkeit durch den Fahrer (Controllability).",
  "## ASIL",
  "Daraus ergibt sich eine Sicherheitsstufe: QM (normales Qualitätsmanagement reicht) oder ASIL A bis D, wobei D die strengsten Anforderungen hat. Ein Sicherheitsziel wie „Kein ungewolltes Antriebsmoment“ erbt den ASIL und bestimmt, wie sorgfältig Hardware und Software entwickelt, geprüft und überwacht werden müssen.",
  "## Was das für das Steuergerät heißt",
  "Sicherheitsrelevante Funktionen brauchen unabhängige Überwachung, Speicherschutz zwischen Softwareteilen verschiedener ASIL, diagnostizierbare Hardware (etwa Lockstep-Kerne, Speicherprüfung) und einen definierten sicheren Zustand."],
  ["ISO 26262: Entwicklung sicherheitsrelevanter Fahrzeugelektronik.", "Bewertung nach Schwere, Häufigkeit, Beherrschbarkeit.", "QM und ASIL A bis D; D ist am strengsten."],
  [S_26262],
  [card("ASIL", "Automotive Safety Integrity Level A bis D; D stellt die höchsten Anforderungen."),
   card("QM", "Quality Management: keine besonderen Sicherheitsanforderungen über normale Qualität hinaus."),
   card("Sicherheitsziel", "Oberste Sicherheitsanforderung, z. B. „kein ungewolltes Antriebsmoment“, mit zugeordnetem ASIL."),
   card("S, E, C", "Severity (Schwere), Exposure (Häufigkeit), Controllability (Beherrschbarkeit): Kriterien der Risikoanalyse.")],
  [mc("Welche Stufe hat die strengsten Anforderungen?", ["ASIL D", "ASIL A", "QM", "ASIL B"], 0, "Die Reihenfolge ist QM, A, B, C, D."),
   multi("Nach welchen Kriterien wird eine Gefährdung bewertet?", ["Schwere", "Häufigkeit der Situation", "Beherrschbarkeit", "Kosten des Bauteils"], [0, 1, 2], "Kosten spielen bei der ASIL-Einstufung keine Rolle."),
   mc("Was ist ein typisches Sicherheitsziel bei der Motorsteuerung?", ["Kein ungewolltes Antriebsmoment", "Möglichst niedriger Verbrauch", "Schneller Motorstart", "Leiser Leerlauf"], 0, "Ungewollte Beschleunigung ist eine zentrale Gefährdung."),
   mc("Warum braucht man Speicherschutz zwischen Softwareteilen?", ["Damit QM-Software keine ASIL-Daten verfälscht", "Damit mehr Speicher frei ist", "Damit die Software schneller startet", "Damit Fehlercodes gelöscht werden"], 0, "Man spricht von Rückwirkungsfreiheit (Freedom from Interference).")]),
 L("ecu.m7.l2", "Das E-Gas-Überwachungskonzept", 7, [
  "Bei elektronischem Gaspedal (E-Gas) gibt es keine mechanische Verbindung zur Drosselklappe mehr. Die Motorsteuerung muss also selbst sicherstellen, dass sie kein ungewolltes Moment erzeugt. Dafür haben deutsche Hersteller und Zulieferer im Arbeitskreis EGAS ein standardisiertes 3-Ebenen-Konzept beschrieben.",
  "## Ebene 1: Funktion",
  "Hier läuft die normale Motorsteuerung: Fahrerwunsch, Momentenstruktur, Einspritzung, Zündung.",
  "## Ebene 2: Funktionsüberwachung",
  "Eine unabhängig programmierte, vereinfachte Berechnung prüft, ob das tatsächlich erzeugte Moment zum zulässigen Moment passt. Sie nutzt eigene Signale und redundant gespeicherte Daten. Ist das Ist-Moment zu hoch, leitet sie eine Fehlerreaktion ein.",
  "## Ebene 3: Rechnerüberwachung",
  "Sie stellt sicher, dass der Rechner für Ebene 2 selbst korrekt arbeitet. Klassisch stellt ein separater Überwachungsbaustein Fragen, die der Controller richtig und rechtzeitig beantworten muss (Frage-Antwort-Verfahren). Antwortet er falsch, kann der Baustein unabhängig die Endstufen abschalten.",
  "## Redundante Fahrpedalsignale",
  "Das Fahrpedal hat zwei unabhängige Sensoren, oft mit unterschiedlichen Kennlinien. Passen sie nicht zusammen, wird die Momentanforderung begrenzt."],
  ["Ebene 1: Funktion · Ebene 2: Funktionsüberwachung · Ebene 3: Rechnerüberwachung.", "Ebene 2 vergleicht Ist-Moment mit zulässigem Moment.", "Ebene 3: Frage-Antwort mit unabhängigem Überwachungsbaustein."],
  [S_EGAS, S_26262],
  [card("E-Gas", "Elektronisches Gaspedal ohne mechanische Verbindung zur Drosselklappe."),
   card("Ebene 2 (EGAS)", "Unabhängige Funktionsüberwachung, die das Ist-Moment gegen das zulässige Moment prüft."),
   card("Ebene 3 (EGAS)", "Rechnerüberwachung, z. B. Frage-Antwort-Verfahren mit separatem Überwachungsbaustein."),
   card("Fahrpedal mit zwei Sensoren", "Redundante Erfassung; Abweichungen führen zur Begrenzung der Momentanforderung.")],
  [order("Ordne die drei EGAS-Ebenen von 1 bis 3.", ["Funktion", "Funktionsüberwachung", "Rechnerüberwachung"], "Jede Ebene überwacht die darunterliegende."),
   mc("Was prüft die Ebene 2?", ["Ob das Ist-Moment zum zulässigen Moment passt", "Ob der Bus funktioniert", "Ob die Batterie voll ist", "Ob der Fehlerspeicher leer ist"], 0, "Sie ist eine unabhängige Plausibilisierung der Momentenberechnung."),
   mc("Wie überwacht Ebene 3 klassischerweise den Rechner?", ["Frage-Antwort mit einem separaten Baustein", "Mit einem zweiten Fahrpedal", "Über die Werkstatt", "Über die Außentemperatur"], 0, "Falsche oder späte Antworten führen zur Abschaltung."),
   mc("Warum hat das Fahrpedal zwei Sensoren?", ["Um Sensorfehler sicher zu erkennen", "Um die Auflösung zu verdoppeln", "Für Links- und Rechtslenker", "Damit eines als Reserve im Kofferraum liegt"], 0, "Nur der Vergleich zweier unabhängiger Signale deckt Fehler auf.")]),
 L("ecu.m7.l3", "Fehlerreaktionen und Toleranzzeit", 5, [
  "Erkennen allein reicht nicht: Der Fehler muss rechtzeitig zu einer sicheren Reaktion führen.",
  "## Fehlertoleranzzeit",
  "Zwischen dem Auftreten eines Fehlers und einer möglichen Gefährdung vergeht eine gewisse Zeit (Fault Tolerant Time Interval). Erkennung und Reaktion zusammen müssen schneller sein. Bei ungewolltem Moment geht es oft um Bruchteile einer Sekunde.",
  "## Typische Reaktionen",
  "Je nach Fehler: Ersatzwert nutzen, Moment begrenzen, Drosselklappe in Notlaufstellung, Einspritzung einzelner oder aller Zylinder abschalten, im Extremfall Endstufen hardwareseitig sperren. Gleichzeitig wird der Fehler gespeichert und eine Warnung angezeigt.",
  "## Fail-safe statt fail-operational",
  "Für Verbrennungsmotoren genügt meist ein sicherer Zustand durch Abschalten oder Begrenzen. Bei automatisiertem Fahren muss das System dagegen oft weiterarbeiten können (fail-operational), was deutlich mehr Redundanz verlangt."],
  ["Erkennung plus Reaktion müssen innerhalb der Fehlertoleranzzeit liegen.", "Reaktionen: Ersatzwert, Begrenzung, Abschaltung, Endstufen sperren.", "Motor: meist fail-safe; automatisiertes Fahren: oft fail-operational."],
  [S_26262, S_EGAS],
  [card("Fehlertoleranzzeit (FTTI)", "Zeit vom Fehlereintritt bis zu einer möglichen Gefährdung; Erkennung und Reaktion müssen schneller sein."),
   card("Fail-safe", "Bei Fehler wird ein sicherer Zustand eingenommen, etwa durch Abschalten."),
   card("Fail-operational", "Bei Fehler arbeitet das System mit eingeschränkter Funktion sicher weiter.")],
  [mc("Was muss innerhalb der Fehlertoleranzzeit passieren?", ["Fehlererkennung und sichere Reaktion", "Nur die Fehlerspeicherung", "Nur die Anzeige im Kombiinstrument", "Ein Werkstattbesuch"], 0, "Die Reaktion muss greifen, bevor eine Gefährdung entsteht."),
   mc("Welches Prinzip genügt bei Motorsteuerungen meist?", ["Fail-safe", "Fail-operational", "Fail-silent ohne Reaktion", "Keines"], 0, "Abschalten oder Begrenzen führt meist in einen sicheren Zustand."),
   mc("Warum ist fail-operational aufwendiger?", ["Das System muss trotz Fehler weiterarbeiten", "Weil mehr Fehlercodes nötig sind", "Weil es mehr Strom braucht", "Weil die Norm es verbietet"], 0, "Dafür braucht es redundante Sensoren, Rechner und Versorgungen."),
   mc("Welche Reaktion ist die stärkste?", ["Endstufen hardwareseitig sperren", "Ersatzwert verwenden", "Warnleuchte einschalten", "Fehler speichern"], 0, "Sie wirkt unabhängig von der Software.")])
]}

M8 = {"id": "ecu.m8", "level": 3, "title": "Diagnose aus Sicht des Steuergeräts", "desc": "Wie Fehler erkannt, entprellt, gespeichert und über UDS und OBD ausgelesen werden.", "lessons": [
 L("ecu.m8.l1", "Vom Fehlerereignis zum DTC", 7, [
  "Jede Überwachung im Steuergerät meldet ihr Ergebnis als Ereignis: bestanden oder nicht bestanden. Daraus wird ein Fehlercode (DTC, Diagnostic Trouble Code).",
  "## Entprellen",
  "Ein einzelnes „nicht bestanden“ macht noch keinen Fehler. Ein Zähler oder Timer muss eine Schwelle erreichen, bevor der Fehler als bestätigt gilt (zum Beispiel über eine Zählerentprellung, die bei Fehlschlag hoch- und bei Erfolg herunterzählt).",
  "## Statusbits",
  "Jeder DTC hat ein Statusbyte (in ISO 14229 definiert), etwa „Test im aktuellen Zyklus fehlgeschlagen“, „ausstehend“ (pending), „bestätigt“ (confirmed) und „Warnleuchte angefordert“. Abgasrelevante Fehler werden oft erst nach mehreren Fahrzyklen bestätigt.",
  "## Umgebungsdaten",
  "Beim Eintrag speichert das Steuergerät Umgebungsdaten wie Drehzahl, Last, Temperatur oder Kilometerstand. Der Freeze Frame (Snapshot) hilft der Werkstatt später zu verstehen, unter welchen Bedingungen der Fehler auftrat.",
  "## Heilung und Löschen",
  "Läuft die Überwachung wieder fehlerfrei, gilt der Fehler als geheilt; der Eintrag bleibt aber eine Weile im Speicher (Alterung), bis er automatisch gelöscht wird. Eine Werkstatt kann ihn mit UDS-Dienst 0x14 löschen."],
  ["Überwachung → Ereignis → Entprellung → DTC.", "Statusbits: pending, confirmed, Warnleuchte angefordert u. a.", "Freeze Frame speichert die Bedingungen beim Fehler."],
  [S_UDS, S_AUTOSAR],
  [card("DTC", "Diagnostic Trouble Code: gespeicherter Fehlercode."),
   card("Pending DTC", "Ausstehender Fehler: im aktuellen oder letzten Zyklus erkannt, noch nicht bestätigt."),
   card("Confirmed DTC", "Bestätigter Fehler nach Erfüllung der Bestätigungsbedingungen, z. B. über mehrere Fahrzyklen."),
   card("Freeze Frame", "Umgebungsdaten zum Zeitpunkt des Fehlereintrags."),
   card("Alterung (Aging)", "Automatisches Löschen eines geheilten Fehlers nach einer Anzahl fehlerfreier Zyklen.")],
  [order("Ordne den Weg eines Fehlers.", ["Überwachung schlägt fehl", "Entprellung erreicht Schwelle", "DTC wird ausstehend (pending)", "DTC wird bestätigt (confirmed)"], "Erst die Bestätigung führt bei OBD-Fehlern zur Warnleuchte."),
   mc("Was ist ein Freeze Frame?", ["Gespeicherte Umgebungsdaten beim Fehler", "Ein eingefrorener Bildschirm", "Ein gesperrter Flash-Bereich", "Ein Busfehler"], 0, "Er zeigt die Bedingungen, unter denen der Fehler auftrat."),
   mc("Mit welchem UDS-Dienst löscht die Werkstatt Fehler?", ["ClearDiagnosticInformation (0x14)", "ReadDTCInformation (0x19)", "RequestDownload (0x34)", "RoutineControl (0x31)"], 0, "0x19 liest Fehler, 0x14 löscht sie."),
   mc("Was passiert mit einem geheilten Fehler, der nicht gelöscht wird?", ["Er altert und wird später automatisch gelöscht", "Er bleibt für immer", "Er wird sofort gelöscht", "Er wird zum Bus geschickt"], 0, "Die Alterung entfernt ihn nach mehreren fehlerfreien Zyklen.")]),
 L("ecu.m8.l2", "UDS-Sitzungen und Dienste", 6, [
  "Über Unified Diagnostic Services (ISO 14229) spricht ein Tester mit dem Steuergerät. Jede Anfrage beginnt mit einer Dienstkennung (Service ID).",
  "## Sitzungen",
  "Das Steuergerät startet in der Standardsitzung (Default Session, 0x01). Für erweiterte Funktionen wechselt der Tester in die Extended Session (0x03), zum Flashen in die Programming Session (0x02). Ohne regelmäßiges TesterPresent (0x3E) fällt das Steuergerät nach einer Zeit zurück in die Standardsitzung.",
  "## Wichtige Dienste",
  "ReadDataByIdentifier (0x22) liest Werte wie Softwareversion oder Messwerte, WriteDataByIdentifier (0x2E) schreibt sie. ReadDTCInformation (0x19) liest Fehler. RoutineControl (0x31) startet Routinen wie Selbsttests. InputOutputControl (0x2F) steuert Aktoren direkt, etwa für einen Stellgliedtest.",
  "## Antworten",
  "Eine positive Antwort hat die Dienstkennung plus 0x40 (auf 0x22 antwortet das Steuergerät mit 0x62). Eine negative Antwort beginnt mit 0x7F und enthält einen Fehlercode (Negative Response Code), etwa „Sicherheitszugang verweigert“ oder „Bedingungen nicht korrekt“."],
  ["Sitzungen: Default 0x01, Programming 0x02, Extended 0x03.", "Positive Antwort = Service-ID + 0x40; negative beginnt mit 0x7F.", "Wichtige Dienste: 0x22, 0x2E, 0x19, 0x31, 0x2F, 0x3E."],
  [S_UDS],
  [card("UDS 0x22", "ReadDataByIdentifier: liest einen Datenwert über seine Kennung (DID)."),
   card("UDS 0x19", "ReadDTCInformation: liest Fehlercodes und ihren Status."),
   card("UDS 0x2F", "InputOutputControlByIdentifier: steuert Ein- oder Ausgänge direkt, z. B. für Stellgliedtests."),
   card("UDS 0x3E", "TesterPresent: hält eine Nicht-Standardsitzung aufrecht."),
   card("Negative Response 0x7F", "Ablehnung einer Anfrage mit Fehlercode (NRC).")],
  [mc("Ein Tester sendet 0x22. Mit welcher Kennung beginnt die positive Antwort?", ["0x62", "0x22", "0x7F", "0x60"], 0, "0x22 + 0x40 = 0x62."),
   mc("Was passiert ohne TesterPresent in der Extended Session?", ["Rückfall in die Standardsitzung", "Das Steuergerät schaltet ab", "Der Fehlerspeicher wird gelöscht", "Nichts"], 0, "Ein Timeout setzt die Sitzung zurück."),
   mc("Womit beginnt eine negative Antwort?", ["0x7F", "0x40", "0x00", "0xFF"], 0, "Danach folgen die abgelehnte Service-ID und der NRC."),
   mc("Welcher Dienst eignet sich für einen Stellgliedtest?", ["InputOutputControl (0x2F)", "ReadDataByIdentifier (0x22)", "SecurityAccess (0x27)", "ClearDiagnosticInformation (0x14)"], 0, "Damit kann der Tester einen Aktor direkt ansteuern.")]),
 L("ecu.m8.l3", "OBD: Warnleuchte und Bereitschaft", 6, [
  "On-Board-Diagnose (OBD) ist gesetzlich vorgeschrieben: Das Fahrzeug muss abgasrelevante Fehler selbst erkennen und anzeigen.",
  "## Die Warnleuchte",
  "Die Motorkontrollleuchte (MIL, Malfunction Indicator Lamp) leuchtet, wenn ein abgasrelevanter Fehler bestätigt ist. Bei Zündaussetzern, die den Katalysator schädigen können, blinkt sie.",
  "## Readiness",
  "Bestimmte Überwachungen laufen nur unter speziellen Bedingungen, etwa die Katalysatorprüfung bei warmem Motor und konstanter Fahrt. Readiness-Bits zeigen an, ob jede Überwachung seit dem letzten Löschen mindestens einmal gelaufen ist. Bei der Abgasuntersuchung wird das geprüft.",
  "## Wie oft geprüft wird",
  "Die Vorschriften verlangen, dass Überwachungen im Alltag häufig genug laufen. Gemessen wird das als Verhältnis aus Überwachungsdurchläufen und Fahrzyklen (IUMPR, In-Use Monitor Performance Ratio). Dazu mehr in einem eigenen Kurs.",
  "## Zugang",
  "Über die genormte OBD-Buchse kann jedes Diagnosegerät abgasrelevante Daten lesen, etwa über die OBD-Dienste nach SAE J1979 bzw. ISO 15031; neuere Fahrzeuge nutzen zunehmend UDS-basierte OBD (SAE J1979-2)."],
  ["MIL leuchtet bei bestätigtem Abgasfehler, blinkt bei katalysatorschädigenden Aussetzern.", "Readiness: Ist jede Überwachung einmal gelaufen?", "IUMPR misst, wie oft Überwachungen im Alltag laufen."],
  [{"n": "SAE J1979 / J1979-2: OBD-Dienste (E/E Diagnostic Test Modes)", "u": "https://www.sae.org/standards/content/j1979_202104/"}, S_UDS, S_REIF],
  [card("MIL", "Malfunction Indicator Lamp: Motorkontrollleuchte für abgasrelevante Fehler."),
   card("Readiness", "Statusanzeige, ob die einzelnen OBD-Überwachungen seit dem letzten Löschen vollständig gelaufen sind."),
   card("IUMPR", "In-Use Monitor Performance Ratio: Verhältnis von Überwachungsdurchläufen zu Fahrzyklen im Alltag.")],
  [mc("Wann blinkt die Motorkontrollleuchte?", ["Bei katalysatorschädigenden Zündaussetzern", "Bei leerem Tank", "Beim Flashen", "Bei offenem Kofferraum"], 0, "Blinken warnt vor sofortiger Schädigung des Katalysators."),
   mc("Was zeigen Readiness-Bits?", ["Ob jede Überwachung seit dem Löschen gelaufen ist", "Ob der Motor warm ist", "Ob Fehler vorliegen", "Ob das Fahrzeug fahrbereit ist"], 0, "Nach dem Löschen sind sie zunächst nicht gesetzt."),
   mc("Warum ist Fehlerlöschen kurz vor der Abgasuntersuchung keine gute Idee?", ["Die Readiness ist dann nicht erreicht", "Die MIL leuchtet dann dauerhaft", "Das Steuergerät wird gesperrt", "Der Kilometerstand wird gelöscht"], 0, "Fehlende Readiness wird bei der Prüfung erkannt."),
   mc("Was beschreibt IUMPR?", ["Wie oft Überwachungen im Alltag laufen", "Wie viele Fehler gespeichert sind", "Wie schnell der Bus ist", "Wie alt das Steuergerät ist"], 0, "Es ist ein Verhältnis aus Durchläufen und Fahrzyklen.")])
]}
